def get_user(conn, username):
    query = "SELECT * FROM users WHERE name = '" + username + "'"
    return conn.execute(query).fetchone()

# username is the raw form field from the public login endpoint

ALLOWED_TABLES = {"orders", "invoices"}

def count_rows(conn, table, customer_id):
    if table not in ALLOWED_TABLES:
        raise ValueError("unknown table")
    sql = f"SELECT COUNT(*) FROM {table} WHERE customer_id = ?"
    return conn.execute(sql, (customer_id,)).fetchone()[0]

# table and customer_id both come straight from the HTTP request
